import{_ as t,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"搜索 Linux 中的文件和文件夾的四種簡單方法 | LCTT x X-CMD","titleTemplate":false,"description":"搜索 Linux 中的文件和文件夾的四種簡單方法 | LCTT (201812) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"搜索 Linux 中的文件和文件夾的四種簡單方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"搜索 Linux 中的文件和文件夾的四種簡單方法 | LCTT (201812) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux","title":"搜索 Linux 中的文件和文件夾的四種簡單方法","tag":"201812","desc":""},"relativePath":"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux.md","filePath":"[post].md"}'),h={name:"201812/20181203 Four Easy Ways to Search Or Find Files And Folders in Linux.md"};function c(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="搜索-linux-中的文件和文件夾的四種簡單方法" tabindex="-1">搜索 Linux 中的文件和文件夾的四種簡單方法 <a class="header-anchor" href="#搜索-linux-中的文件和文件夾的四種簡單方法" aria-label="Permalink to “搜索 Linux 中的文件和文件夾的四種簡單方法”">​</a></h1><p>Linux 管理員一天都不能離開搜索文件，因為這是他們的日常活動。瞭解一些搜索的東西是不錯的，因為這能幫助你在命令列服務器中工作。這些命令記憶起來不復雜，因為它們使用的是標準語法。</p><p>可以通過四個 Linux 命令啦執行此操作，每個命令都有自己獨特的功能。</p><h3 id="方法-1-使用-find-命令在-linux-中搜索文件和文件夾" tabindex="-1">方法 1：使用 find 命令在 Linux 中搜索文件和文件夾 <a class="header-anchor" href="#方法-1-使用-find-命令在-linux-中搜索文件和文件夾" aria-label="Permalink to “方法 1：使用 find 命令在 Linux 中搜索文件和文件夾”">​</a></h3><p><code>find</code> 命令被廣泛使用，並且是在 Linux 中搜索文件和文件夾的著名命令。它搜索當前目錄中的給定文件，並根據搜索條件遞歸遍歷其子目錄。</p><p>它允許用户根據大小、名稱、所有者、組、類型、權限、日期和其他條件執行所有類型的文件搜索。</p><p>運行以下命令以在系統中查找給定文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -iname &quot;sshd_config&quot;</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span></code></pre></div><p>運行以下命令以查找系統中的給定文件夾。要在 Linux 中搜索文件夾，我們需要使用 <code>-type</code> 參數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d -iname &quot;ssh&quot;</span></span>
<span class="line"><span>/usr/lib/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/usr/lib/go/pkg/linux_amd64/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/etc/ssh</span></span></code></pre></div><p>使用通配符搜索系統上的所有文件。我們將搜索系統中所有以 <code>.config</code> 為擴展名的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -name &quot;*.config&quot;</span></span>
<span class="line"><span>/usr/lib/mono/gac/avahi-sharp/1.0.0.0__4d116c78973743f5/avahi-sharp.dll.config</span></span>
<span class="line"><span>/usr/lib/mono/gac/avahi-ui-sharp/0.0.0.0__4d116c78973743f5/avahi-ui-sharp.dll.config</span></span>
<span class="line"><span>/usr/lib/python2.7/config/Setup.config</span></span>
<span class="line"><span>/usr/share/git/mw-to-git/t/test.config</span></span>
<span class="line"><span>/var/lib/lightdm/.config</span></span>
<span class="line"><span>/home/daygeek/.config</span></span>
<span class="line"><span>/root/.config</span></span>
<span class="line"><span>/etc/skel/.config</span></span></code></pre></div><p>使用以下命令格式在系統中查找空文件和文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -empty</span></span></code></pre></div><p>使用以下命令組合查找 Linux 上包含特定文本的所有文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type f -exec grep &quot;Port 22&quot; &#39;{}&#39; \\; -print</span></span>
<span class="line"><span># find / -type f -print | xargs grep &quot;Port 22&quot;</span></span>
<span class="line"><span># find / -type f | xargs grep &#39;Port 22&#39;</span></span>
<span class="line"><span># find / -type f -exec grep -H &#39;Port 22&#39; {} \\;</span></span></code></pre></div><h3 id="方法-2-使用-locate-命令在-linux-中搜索文件和文件夾" tabindex="-1">方法 2：使用 locate 命令在 Linux 中搜索文件和文件夾 <a class="header-anchor" href="#方法-2-使用-locate-命令在-linux-中搜索文件和文件夾" aria-label="Permalink to “方法 2：使用 locate 命令在 Linux 中搜索文件和文件夾”">​</a></h3><p><code>locate</code> 命令比 <code>find</code> 命令運行得更快，因為它使用 <code>updatedb</code> 資料庫，而 <code>find</code> 命令在真實系統中搜索。</p><p>它使用資料庫而不是搜索單個目錄路徑來獲取給定文件。</p><p><code>locate</code> 命令未在大多數發行版中預安裝，因此，請使用你的包管理器進行安裝。</p><p>資料庫通過 cron 任務定期更新，但我們可以通過運行以下命令手動更新它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo updatedb</span></span></code></pre></div><p>只需運行以下命令即可列出給定的文件或文件夾。在 <code>locate</code> 命令中不需要指定特定選項來打印文件或文件夾。</p><p>在系統中搜索 <code>ssh</code> 文件夾。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\ssh&#39;</span></span>
<span class="line"><span>/etc/ssh</span></span>
<span class="line"><span>/usr/bin/ssh</span></span>
<span class="line"><span>/usr/lib/ssh</span></span>
<span class="line"><span>/usr/lib/go/pkg/linux_amd64/cmd/vendor/golang.org/x/crypto/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/go/testdata/failssh/ssh</span></span>
<span class="line"><span>/usr/lib/go/src/cmd/vendor/golang.org/x/crypto/ssh</span></span></code></pre></div><p>在系統中搜索 <code>ssh_config</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># locate --basename &#39;\\sshd_config&#39;</span></span>
<span class="line"><span>/etc/ssh/sshd_config</span></span></code></pre></div><h3 id="方法-3-在-linux-中搜索文件使用-which-命令" tabindex="-1">方法 3：在 Linux 中搜索文件使用 which 命令 <a class="header-anchor" href="#方法-3-在-linux-中搜索文件使用-which-命令" aria-label="Permalink to “方法 3：在 Linux 中搜索文件使用 which 命令”">​</a></h3><p><code>which</code> 返回在終端輸入命令時執行的可執行文件的完整路徑。</p><p>當你想要為可執行文件創建桌面快捷方式或符號鏈接時，它非常有用。</p><p><code>which</code> 命令搜索當前用户而不是所有用户的 <code>$PATH</code> 環境變量中列出的目錄。我的意思是，當你登錄自己的帳户時，你無法搜索 root 用户文件或目錄。</p><p>運行以下命令以打印 <code>vim</code> 可執行文件的完整路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which vi</span></span>
<span class="line"><span>/usr/bin/vi</span></span></code></pre></div><p>或者，它允許用户一次執行多個文件搜索。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># which -a vi sudo</span></span>
<span class="line"><span>/usr/bin/vi</span></span>
<span class="line"><span>/bin/vi</span></span>
<span class="line"><span>/usr/bin/sudo</span></span>
<span class="line"><span>/bin/sudo</span></span></code></pre></div><h3 id="方法-4-使用-whereis-命令在-linux-中搜索文件" tabindex="-1">方法 4：使用 whereis 命令在 Linux 中搜索文件 <a class="header-anchor" href="#方法-4-使用-whereis-命令在-linux-中搜索文件" aria-label="Permalink to “方法 4：使用 whereis 命令在 Linux 中搜索文件”">​</a></h3><p><code>whereis</code> 命令用於搜索給定命令的二進制、源碼和手冊頁文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># whereis vi</span></span>
<span class="line"><span>vi: /usr/bin/vi /usr/share/man/man1/vi.1p.gz /usr/share/man/man1/vi.1.gz</span></span></code></pre></div><hr>`,39)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),i(n,{href:"https://www.2daygeek.com/four-easy-ways-to-search-or-find-files-and-folders-in-linux/"},{default:e(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/four-easy-ways-to-search-or-find-files-and-folders-in-linux/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),i(n,{href:"https://www.2daygeek.com/author/prakash/"},{default:e(()=>[...s[2]||(s[2]=[a("Prakash Subramanian",-1)])]),_:1}),s[7]||(s[7]=a(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 譯者：",-1)),i(n,{href:"https://github.com/geekpi"},{default:e(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[a("Linux中國",-1)])]),_:1}),s[14]||(s[14]=a(" 榮譽推出",-1))])])}const v=t(h,[["render",c]]);export{y as __pageData,v as default};
